// jsPDF + autoTable are loaded on demand (only when a PDF report is generated) so the main bundle stays well under the PWA precache limit.
let jsPDF = null;
let autoTable = null;
async function loadPdfLibs() {
  if (jsPDF && autoTable) return;
  const [a, b] = await Promise.all([import('jspdf'), import('jspdf-autotable')]);
  jsPDF = a.default || a.jsPDF; autoTable = b.default || b.autoTable;
}
