const REVELECT_LOGO = "data:image/png;base64,";
const REVINANCE_LOGO = "data:image/png;base64,";
// In-app brand mark (line version). Used as a CSS mask so it takes the current text colour and adapts to light/dark.
// NOT used for the original Revinance wordmark (split-bill cards) or the PDF header/watermark, which keep RV_LOGO_FULL / REVINANCE_LOGO.
const RV_MARK_FINE = "data:image/png;base64,";
const RV_MARK_BOLD = "data:image/png;base64,";
const RV_LOGO_FULL = "data:image/png;base64,";
const RV_LOGO_FULL_RATIO = 640 / 86;
// Loading indicator: the REVINANCE outline mark being drawn stroke by stroke (no text).
function RvLoader({ size = 28, className = '', style }) {
  return (
    <svg role="img" aria-label="loading" className={`fc-rvdraw${className ? ' ' + className : ''}`} viewBox="350 55 820 685" style={{ width: Math.round(size * 1.2), height: size, ...style }}>
      <g fill="none" strokeWidth="11" strokeLinecap="round" strokeLinejoin="round">
        <path pathLength="1" className="fc-rvdraw-p fc-rvdraw-p1" d="M 377,680 L 377,309 C 377,251 416,201 478,183 L 1080,73 Q 1093,70 1093,83 L 1093,228" />
        <path pathLength="1" className="fc-rvdraw-p fc-rvdraw-p1" d="M 377,680 L 446,647" />
        <path pathLength="1" className="fc-rvdraw-p fc-rvdraw-p2" d="M 449,719 L 449,555 C 449,478 494,411 571,371 C 592,360 613,351 637,345 L 1110,230 Q 1145,221 1145,255 L 1145,351 C 1145,374 1131,390 1108,397" />
        <path pathLength="1" className="fc-rvdraw-p fc-rvdraw-p3" d="M 449,719 L 479,667 C 514,606 558,554 624,527 C 644,519 663,514 683,509 L 1112,391 Q 1146,382 1146,414 L 1146,602 C 1146,651 1111,693 1060,708 C 1044,716 1029,720 1008,720 Z" />
      </g>
    </svg>
  );
}
function RvMark({ size = 20, color, loading = false, bold, className = '', style }) {
  const c = !color ? undefined : /gold/.test(color) ? 'var(--fc-logo)' : color;
  const useBold = bold !== undefined ? bold : size <= 30;
  return <span aria-hidden="true" className={`fc-rvmark${useBold ? ' fc-rvmark-bold' : ''}${loading ? ' fc-rvmark-loading' : ''}${className ? ' ' + className : ''}`} style={{ width: Math.round(size * 1.12), color: c, ...style }} />;
}
// Drop-in replacement for the old lucide <Sparkles/> icon so every AI/Revi touchpoint shows the brand mark.
function Sparkles({ size = 16, color, className, loading, style }) { return <RvMark size={size} color={color} className={className} loading={loading} style={style} />; }

