const PIE_RADIAN = Math.PI / 180;
// Icon badges around a donut. Every slice keeps its icon: when neighbouring slices are too thin for their badges to fit
// side by side, the badges are fanned out along the ring (never dropped) and joined to their slice by a short leader line.
const PIE_BADGE = 26;
function spreadPieAngles(values, r) {
  const total = values.reduce((x, y) => x + y, 0) || 1; let cum = 0;
  const true_ = values.map(v => { const m = 90 - 360 * (cum + v / 2) / total; cum += v; return m; });
  const adj = true_.slice(); const n = adj.length;
  const sep = 2 * Math.asin(Math.min(1, (PIE_BADGE + 4) / (2 * r))) * 180 / Math.PI;
  if (n < 2 || n * sep >= 360) return { true_, adj };
  for (let pass = 0; pass < 80; pass++) {
    let moved = false;
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n; const g = j === 0 ? adj[i] - adj[0] + 360 : adj[i] - adj[j];
      if (g < sep - 0.01) { const d = (sep - g) / 2; adj[i] += d; adj[j] -= d; moved = true; }
    }
    if (!moved) break;
  }
  return { true_, adj };
}
function makePieIconLabel(data, colorOf) {
  const cache = {};
  return function PieIconLabel(props) {
    const { cx, cy, outerRadius, index } = props;
    const entry = data[index];
    if (!entry) return null;
    const IconComp = CAT_ICONS[entry.key] || MoreHorizontal;
    const color = (colorOf && colorOf(entry)) || CAT_COLORS[entry.key] || '#786b5a';
    const r = outerRadius + 16;
    const k = Math.round(outerRadius);
    const ang = cache[k] || (cache[k] = spreadPieAngles(data.map(d => Number(d.value) || 0), r));
    const a = ang.adj[index], t0 = ang.true_[index];
    const x = cx + r * Math.cos(-a * PIE_RADIAN), y = cy + r * Math.sin(-a * PIE_RADIAN);
    const fan = Math.abs(a - t0) > 2;
    const hx = cx + (outerRadius + 2) * Math.cos(-t0 * PIE_RADIAN), hy = cy + (outerRadius + 2) * Math.sin(-t0 * PIE_RADIAN);
    return (
      <g>
        {fan && <line x1={hx} y1={hy} x2={x} y2={y} stroke={color} strokeWidth={1.2} opacity={0.7} />}
        <g transform={`translate(${x - 13}, ${y - 13})`}>
          <circle cx={13} cy={13} r={13} fill="var(--fc-surface)" stroke={color} strokeWidth={1.5} />
          <g transform="translate(6,6)">
            <IconComp size={14} color={color} strokeWidth={2} />
          </g>
        </g>
      </g>
    );
  };
}
// Donut with icon badges. Keeps the original size (outer radius 78px) and only shrinks when its box is too narrow for the badges.
function useBoxWidth() {
  const ref = useRef(null); const [w, setW] = useState(0);
  useEffect(() => {
    const el = ref.current; if (!el) return undefined;
    const measure = () => setW(el.clientWidth || 0);
    measure();
    let ro = null;
    try { ro = new ResizeObserver(measure); ro.observe(el); } catch (e) { /* older browsers: measured once */ }
    return () => { try { if (ro) ro.disconnect(); } catch (e) { /* ignore */ } };
  }, []);
  return [ref, w];
}
function useIsDesktop() {
  const q = '(min-width: 781px)';
  const [d, setD] = useState(() => { try { return window.matchMedia(q).matches; } catch (e) { return false; } });
  useEffect(() => {
    let m; try { m = window.matchMedia(q); } catch (e) { return undefined; }
    const on = () => setD(m.matches);
    try { m.addEventListener('change', on); } catch (e) { try { m.addListener(on); } catch (e2) { /* ignore */ } }
    return () => { try { m.removeEventListener('change', on); } catch (e) { try { m.removeListener(on); } catch (e2) { /* ignore */ } } };
  }, []);
  return d;
}
function IconDonut({ data, colorOf, height: baseHeight = 250, selected = null, onSelect, tooltip, center }) {
  const [ref, w] = useBoxWidth();
  const desktop = useIsDesktop(); // phones keep the original size; wide screens get a bigger donut
  const height = desktop ? baseHeight + 50 : baseHeight;
  const half = Math.min(w > 0 ? w : 9999, height) / 2;
  const outer = Math.max(36, Math.min(desktop ? 100 : 78, Math.floor(half - 31))); // badge (26) + gap (16-13) + safety must fit inside the box
  const inner = Math.round(outer * 54 / 78);
  return (
    <div className="fc-donut-wrap" ref={ref}>
      <ResponsiveContainer width="100%" height={height}>
        <PieChart margin={{ top: 0, right: 0, bottom: 0, left: 0 }}>
          <Pie data={data} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={inner} outerRadius={outer}
            paddingAngle={4} cornerRadius={8} startAngle={90} endAngle={-270} stroke="none" isAnimationActive={false}
            label={makePieIconLabel(data, colorOf)} labelLine={false} onClick={onSelect ? (_, i) => onSelect(i) : undefined}>
            {data.map((d, i) => <Cell key={d.key} fill={(colorOf && colorOf(d)) || CAT_COLORS[d.key] || '#786b5a'} opacity={selected === null || selected === i ? 1 : 0.35} style={onSelect ? { cursor: 'pointer', outline: 'none' } : { outline: 'none' }} />)}
          </Pie>
          {tooltip}
        </PieChart>
      </ResponsiveContainer>
      <div className="fc-donut-center" style={{ maxWidth: Math.max(60, inner * 2 - 14) }}>{center}</div>
    </div>
  );
}

// Local calendar date, not UTC — Date#toISOString() converts to UTC first, which for a
// UTC+7 user means the date wouldn't roll over until 7am local time. This reads the
// device's own year/month/day instead, so midnight local time is midnight here too.
const todayISO = () => toLocalISO(nowInTz());
// ---- User timezone (Settings → Timezone). null = follow the device. All "today / this month / now" logic goes through nowInTz(),
// which returns a Date whose LOCAL fields show the wall-clock time in the chosen zone (so toLocalISO / monthKey keep working).
let APP_TZ = null;
const TZ_LS = 'rv_tz';
const isValidTz = (z) => { if (!z || typeof z !== 'string') return false; try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return true; } catch (e) { return false; } };
try { const z = localStorage.getItem(TZ_LS); if (isValidTz(z)) APP_TZ = z; } catch (e) { /* ignore */ }
function nowInTz(base) {
  const d = base || new Date();
  if (!APP_TZ) return d;
  try {
    const p = {};
    new Intl.DateTimeFormat('en-US', { timeZone: APP_TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
      .formatToParts(d).forEach(x => { p[x.type] = x.value; });
    return new Date(Number(p.year), Number(p.month) - 1, Number(p.day), Number(p.hour) % 24, Number(p.minute), Number(p.second));
  } catch (e) { return d; }
}
const TZ_OPTIONS = ['Pacific/Honolulu', 'America/Anchorage', 'America/Los_Angeles', 'America/Denver', 'America/Chicago', 'America/New_York', 'America/Sao_Paulo', 'UTC', 'Europe/London', 'Europe/Paris', 'Europe/Athens', 'Europe/Moscow', 'Asia/Dubai', 'Asia/Karachi', 'Asia/Dhaka', 'Asia/Bangkok', 'Asia/Jakarta', 'Asia/Singapore', 'Asia/Makassar', 'Asia/Tokyo', 'Asia/Jayapura', 'Australia/Sydney', 'Pacific/Auckland'];
const TZ_NAMES = { 'Pacific/Honolulu': 'Honolulu', 'America/Anchorage': 'Alaska', 'America/Los_Angeles': 'Los Angeles', 'America/Denver': 'Denver', 'America/Chicago': 'Chicago', 'America/New_York': 'New York', 'America/Sao_Paulo': 'São Paulo', 'UTC': 'UTC', 'Europe/London': 'London', 'Europe/Paris': 'Paris / Berlin', 'Europe/Athens': 'Athens / Cairo', 'Europe/Moscow': 'Moscow / Istanbul', 'Asia/Dubai': 'Dubai', 'Asia/Karachi': 'Karachi', 'Asia/Dhaka': 'Dhaka', 'Asia/Bangkok': 'Bangkok / Vietnam', 'Asia/Jakarta': 'Jakarta (WIB)', 'Asia/Singapore': 'Singapore / KL / Manila', 'Asia/Makassar': 'Makassar / Bali (WITA)', 'Asia/Tokyo': 'Tokyo / Seoul', 'Asia/Jayapura': 'Jayapura (WIT)', 'Australia/Sydney': 'Sydney', 'Pacific/Auckland': 'Auckland' };
function tzOffsetLabel(z) {
  try {
    const x = new Intl.DateTimeFormat('en-US', { timeZone: z, timeZoneName: 'longOffset' }).formatToParts(new Date()).find(q => q.type === 'timeZoneName')?.value || 'GMT';
    const m = x.replace('GMT', 'UTC'); return m === 'UTC' ? 'UTC±0' : m.replace(/:00$/, '');
  } catch (e) { return 'UTC'; }
}
// Same fix, for any Date object (recurring due dates, week buckets, upcoming windows) —
