// Every credit-consuming AI call goes through here: one operation id per user action. The server counts a credit only
// when the operation succeeds; failures, cancellations and duplicate ids are free.
async function invokeAi(fn, body) {
  const res = await supabase.functions.invoke(fn, { body: { ...body, opId: newOpId() } });
  try { window.dispatchEvent(new Event('rv-credits-changed')); } catch (e) { /* ignore */ }
  return res;
}
