    await supabase.from('finance_settings').upsert({ user_id: userId, currency: APP_CCY }, { onConflict: 'user_id' });
    if (APP_CCY !== 'IDR' && (!fxReady('IDR', APP_CCY) || !FX_AT || Date.now() - FX_AT > FX_TTL_MS)) refreshFx(false);
