  const withTrip = (prefill, fillAcct = true) => (tripCtx && prefill && (!prefill.type || prefill.type === 'expense') && !prefill.tripId
    ? { ...prefill, type: 'expense', tripId: tripCtx.id, accountId: prefill.accountId || (fillAcct ? tripCtx.accountId : '') || '' } : prefill);
  const recurringItems = useMemo(() => recurringRaw.map(normRecurring), [recurringRaw, fxTick]); // eslint-disable-line
  const budgets = useMemo(() => normBudgetMap(budgetsRaw), [budgetsRaw, fxTick]); // eslint-disable-line
