  const fxProblem = FX_FAILED && (APP_CCY !== 'IDR' || accountsRaw.some(a => a.currency !== 'IDR') || transactionsRaw.some(x => x.currency !== 'IDR') || debtsRaw.some(x => x.currency !== 'IDR') || receivablesRaw.some(x => x.currency !== 'IDR') || savingGoalsRaw.some(x => x.currency !== 'IDR') || recurringRaw.some(x => x.currency !== 'IDR') || Object.values(budgetsRaw).some(x => x.currency !== 'IDR') || Object.values(investBudgetsRaw).some(x => x.currency !== 'IDR'));
