  const savingsTarget = useMemo(() => { const v = toBaseIdr(savingsTargetRaw.amount, savingsTargetRaw.currency); return v === null ? 0 : v; }, [savingsTargetRaw, fxTick]); // eslint-disable-line -- IDR-base view
