// Revi gets the SAME numbers the app shows: the IDR-base views converted ONCE into the Display Currency through convertAmt
// (no separate conversion in Revi / the edge function), plus the currency code so it never has to guess. Ratios are unitless and untouched.
// Pro-only "advanced" Revi context, built from the app's own already-loaded records (IDR-base views) and converted ONCE via `cv`
// (same conversion the snapshot uses). Nothing is invented: missing months stay missing, statuses are passed as recorded, and the
// Investment Plan (intentions) is kept apart from the Portfolio (actual holdings, shown at cost basis only).
function buildAdvancedRevi(src, cv) {
  const { transactions = [], monthlyRows = [], selectedMonth, budgets = {}, debts = [], receivables = [], savingGoals = [], investBudgets = {}, portfolioTrades = [] } = src;
  const mapObj = (o) => Object.fromEntries(Object.entries(o || {}).map(([k, v]) => [k, cv(v)]));
  const byMonth = {}; monthlyRows.forEach(r => { byMonth[r.monthKey] = r; });
  const months = [];
  for (let i = 11; i >= 0; i--) { const k = prevMonthKey(selectedMonth, i); const r = byMonth[k]; if (r && (r.income > 0 || r.expense > 0 || r.debtPaid > 0 || r.invested > 0)) months.push(k); }
  const catByMonth = {};
  transactions.forEach(tx => { if (tx.type !== 'expense') return; const mk = tx.date.slice(0, 7); if (!months.includes(mk)) return; const o = catByMonth[mk] || (catByMonth[mk] = {}); o[tx.category] = (o[tx.category] || 0) + (Number(tx.amount) || 0); });
  const monthlyHistory = months.map(k => { const r = byMonth[k]; return { month: k, income: cv(r.income), expense: cv(r.expense), debtPaid: cv(r.debtPaid), invested: cv(r.invested), net: cv(r.net), savingsRate: r.income > 0 ? Number(((r.income - r.expense - r.debtPaid) / r.income).toFixed(3)) : null, byCategory: mapObj(catByMonth[k]) }; });
  const budgetHistory = Object.entries(budgets).filter(([, lim]) => Number(lim) > 0).map(([cat, lim]) => ({
    category: cat, limit: cv(lim), monthsObserved: months.length,
    monthsOver: months.filter(k => ((catByMonth[k] || {})[cat] || 0) > Number(lim)).length,
  }));
  const { pos } = pfComputePositions(portfolioTrades);
  const holdings = Object.values(pos).filter(p => p.qty > 0).map(p => ({ asset: p.asset, quantity: Number(p.qty.toFixed(8)), costBasis: cv(Math.round(p.cost)) }));
  return {
    monthlyHistory, budgetHistory,
    receivables: receivables.map(r => ({ name: r.name, remaining: cv(r.amount), dueDate: r.dueDate || null, status: r.status || 'active' })),
    debtsDetail: debts.map(d => ({ name: d.name, remaining: cv(d.remaining), total: cv(d.total), monthlyPlan: cv(d.monthlyPlan), dueDate: d.dueDate || null })),
    savingGoals: savingGoals.map(g => ({ name: g.name, target: cv(g.target), current: cv(g.current), targetDate: g.targetDate || null })),
    investmentPlan: mapObj(investBudgets), // monthly TARGETS per category (intentions)
    ...(holdings.length ? { portfolio: { note: 'actual holdings at average cost, not market value', holdings } } : {}),
  };
}
function buildReviSnapshot(s) {
  const code = APP_CCY !== 'IDR' && fxReady('IDR', APP_CCY) ? APP_CCY : 'IDR';
  const cv = (v) => (v == null || !isFinite(Number(v)) ? v : (code === 'IDR' ? v : roundCcy(convertAmt(Number(v), 'IDR', code), code)));
  const map = (o) => (o ? Object.fromEntries(Object.entries(o).map(([k, v]) => [k, cv(v)])) : o);
  const { advancedSrc, ...base } = s;
  return {
    ...base, currency: code,
    income: cv(s.income), expense: cv(s.expense), debtPaid: cv(s.debtPaid), invested: cv(s.invested), investable: cv(s.investable),
    categoryBreakdown: map(s.categoryBreakdown), budgets: map(s.budgets),
    debts: (s.debts || []).map(d => ({ ...d, remaining: cv(d.remaining), total: cv(d.total), monthlyPlan: cv(d.monthlyPlan) })),
    totalDebtRemaining: cv(s.totalDebtRemaining), investmentPlanMonthly: cv(s.investmentPlanMonthly),
    ...(advancedSrc ? { advanced: buildAdvancedRevi(advancedSrc, cv) } : {}), // Pro only; the server also strips it for Free
  };
}
// ---- Ask Revi actions ----------------------------------------------------------------------------------------------
// Revi only PROPOSES changes. These are validated here (again, after the server did), shown on a confirmation card, and
// applied only when the user taps Apply — through the same save functions the manual screens use.
function normalizeReviActions(raw, isPro) {
  if (!Array.isArray(raw)) return [];
  const num = (v) => { const n = Number(v); return Number.isFinite(n) && n > 0 && n < 1e13 ? roundCcy(n, APP_CCY) : null; };
  const dt = (v) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);
  const str = (v, m) => (typeof v === 'string' ? v.trim().slice(0, m) : '');
  const merged = { set_budget: new Map(), set_invest_plan: new Map() };
  const rest = [];
  for (const a of raw.slice(0, 6)) {
    if (!a || typeof a !== 'object') continue;
    if (a.type === 'set_budget' || a.type === 'set_invest_plan') {
      const allowed = a.type === 'set_budget' ? EXPENSE_CATS : INVESTMENT_CATS;
      for (const it of Array.isArray(a.items) ? a.items.slice(0, 20) : []) {
        const amount = num(it && it.amount);
        if (it && allowed.includes(it.category) && amount !== null) merged[a.type].set(it.category, amount);
      }
    } else if (a.type === 'create_saving_goal') {
      const name = str(a.name, 60), target = num(a.target);
      if (name && target !== null) rest.push({ type: 'create_saving_goal', name, target, targetDate: dt(a.targetDate) });
    } else if (a.type === 'create_trip') {
      const name = str(a.name, 60), budget = num(a.budget);
      if (name && budget !== null) rest.push({ type: 'create_trip', name, destination: str(a.destination, 60), budget, tripCurrency: isCcy(a.tripCurrency) ? a.tripCurrency : null, startDate: dt(a.startDate), endDate: dt(a.endDate), proOnly: !isPro });
    }
  }
  const out = [];
  if (merged.set_budget.size) out.push({ type: 'set_budget', items: [...merged.set_budget].map(([category, amount]) => ({ category, amount })) });
  if (merged.set_invest_plan.size) out.push({ type: 'set_invest_plan', items: [...merged.set_invest_plan].map(([category, amount]) => ({ category, amount })) });
  return [...out, ...rest];
}

function ReviActionCard({ t, actions, state, onApply, onDismiss, api }) {
  const ccy = APP_CCY;
  const wasTxt = (cell) => (cell && Number(cell.amount) > 0 ? ` (${t.reviWas.replace('{x}', fmtMoney(cell.amount, cell.currency || ccy))})` : '');
  const lines = [];
  actions.forEach((a, ai) => {
    if (a.type === 'set_budget') a.items.forEach(it => lines.push({ k: `b${ai}${it.category}`, l: t.reviLnBudget.replace('{c}', t.categories[it.category] || it.category), v: `${fmtMoney(it.amount, ccy)}${t.reviPerMonth}${wasTxt(api.budgets[it.category])}` }));
    else if (a.type === 'set_invest_plan') a.items.forEach(it => lines.push({ k: `i${ai}${it.category}`, l: t.reviLnInvest.replace('{c}', t.categories[it.category] || it.category), v: `${fmtMoney(it.amount, ccy)}${t.reviPerMonth}${wasTxt(api.invest[it.category])}` }));
    else if (a.type === 'create_saving_goal') lines.push({ k: `g${ai}`, l: `${t.reviLnGoal}: ${a.name}`, v: `${fmtMoney(a.target, ccy)}${a.targetDate ? ` · ${a.targetDate}` : ''}` });
    else if (a.type === 'create_trip') lines.push({ k: `t${ai}`, l: `${t.reviLnTrip}: ${a.name}${a.destination ? ` — ${a.destination}` : ''}`, v: `${fmtMoney(a.budget, ccy)}${a.startDate ? ` · ${a.startDate}${a.endDate ? ' → ' + a.endDate : ''}` : ''}`, pro: a.proOnly });
  });
  const budgetTotal = actions.filter(a => a.type === 'set_budget').reduce((sum, a) => sum + a.items.reduce((x, it) => x + it.amount, 0), 0);
  return (
    <div className="fc-revi-act" data-testid="revi-actions">
      <div className="fc-revi-act-title"><Sparkles size={13} /> {t.reviActTitle}</div>
      <div className="fc-revi-act-list">
        {lines.map(ln => (
          <div key={ln.k} className="fc-revi-act-row"><span>{ln.l}</span><b>{ln.v}</b>{ln.pro && <em>{t.reviTripPro}</em>}</div>
        ))}
        {budgetTotal > 0 && actions.filter(a => a.type === 'set_budget').some(a => a.items.length > 1) && <div className="fc-revi-act-total">{t.reviBudgetLeft.replace('{n}', fmtMoney(budgetTotal, ccy))}{t.reviPerMonth}</div>}
      </div>
      {state === 'pending' || state === 'applying' ? (
        <div className="fc-revi-act-btns">
          <button type="button" className="fc-btn-primary" data-testid="revi-apply" disabled={state === 'applying'} onClick={onApply}>{t.reviApply}</button>
          <button type="button" className="fc-btn-ghost" data-testid="revi-dismiss" disabled={state === 'applying'} onClick={onDismiss}>{t.reviDismiss}</button>
        </div>
      ) : (
        <div className="fc-revi-act-state" data-testid="revi-state">{state === 'applied' ? `✓ ${t.reviApplied}` : state === 'dismissed' ? t.reviDismissed : t.reviApplyFail}</div>
      )}
    </div>
  );
}

