function pdfMonthKeys(endKey, n) {
  const [y, m] = endKey.split('-').map(Number);
  const out = [];
  for (let i = n - 1; i >= 0; i--) out.push(monthKey(new Date(y, m - 1 - i, 1)));
  return out;
}
const pdfLocale = (lang) => (lang === 'id' ? 'id-ID' : 'en-US');
function pdfMonthLong(key, lang) { const [y, m] = key.split('-').map(Number); return new Date(y, m - 1, 1).toLocaleDateString(pdfLocale(lang), { month: 'long', year: 'numeric' }); }
function pdfMonthName(key, lang) { const [y, m] = key.split('-').map(Number); return new Date(y, m - 1, 1).toLocaleDateString(pdfLocale(lang), { month: 'long' }); }
function pdfMonthShort(key, lang) { const [y, m] = key.split('-').map(Number); return new Date(y, m - 1, 1).toLocaleDateString(pdfLocale(lang), { month: 'short' }); }
function pdfRangeLabel(keys, lang) {
  const a = keys[0], b = keys[keys.length - 1];
  if (a === b) return pdfMonthLong(b, lang);
  const sameYear = a.slice(0, 4) === b.slice(0, 4);
  return `${sameYear ? pdfMonthName(a, lang) : pdfMonthLong(a, lang)} — ${pdfMonthLong(b, lang)}`;
}
// jsPDF's built-in fonts only cover Latin-1 + €, so symbols they can't draw (₩ ฿ د.إ) and the ambiguous ¥ use the ISO code in PDFs.
const PDF_SYM = { IDR: 'Rp', USD: '$', EUR: '€', GBP: '£', CNY: 'CNY ', JPY: 'JPY ', SGD: 'S$', MYR: 'RM', THB: 'THB ', AED: 'AED ', KRW: 'KRW ' };
// Total of several IDR-base amounts = sum of the same rounded figures the table rows print (no cent drift between total and rows).
function pdfSumMoney(list) { const r = sumDisp(list); return r.ccy === 'IDR' ? pdfMoney(r.v) : pdfFmtDisp(r.v); }
function pdfFmtDisp(r) { const m = CURRENCY_META[APP_CCY]; return `${r < 0 ? '-' : ''}${PDF_SYM[APP_CCY]}${Math.abs(r).toLocaleString('en-US', { minimumFractionDigits: m.dec, maximumFractionDigits: m.dec })}`; }
function pdfMoney(n) {
  if (APP_CCY !== 'IDR') { // same single conversion path as the app: IDR-base -> Display Currency via convertAmt
    const c = convertAmt(n, 'IDR', APP_CCY);
    if (c !== null) return pdfFmtDisp(roundCcy(c, APP_CCY));
  }
  const v = Math.round(Number(n) || 0); return `${v < 0 ? '-' : ''}Rp${Math.abs(v).toLocaleString('id-ID')}`;
}
function pdfPct(v, lang, digits = 1) { if (v == null || !isFinite(v)) return '-'; const s = (v * 100).toFixed(digits); return `${lang === 'id' ? s.replace('.', ',') : s}%`; }
// Original-currency tag for a foreign transaction (ISO code, so jsPDF's Latin-1 fonts can draw it). Empty when it already is the Display Currency.
function pdfOrig(tx) { return tx && tx.currency && tx.currency !== APP_CCY && tx.origAmount != null && isCcy(tx.currency) ? ` [${tx.currency} ${roundCcy(tx.origAmount, tx.currency).toLocaleString('en-US', { minimumFractionDigits: CURRENCY_META[tx.currency].dec, maximumFractionDigits: CURRENCY_META[tx.currency].dec })}]` : ''; }
function pdfSigned(n) { const v = Math.round(Number(n) || 0); return `${v > 0 ? '+' : ''}${pdfMoney(v)}`; }
function pdfAxis(v, lang) {
  if (APP_CCY !== 'IDR') { const u = convertAmt(v, 'IDR', APP_CCY); if (u !== null) { const au = Math.abs(u); const sg = u < 0 ? '-' : ''; const y = PDF_SYM[APP_CCY]; return au >= 1e9 ? `${sg}${y}${(au / 1e9).toFixed(1)}B` : au >= 1e6 ? `${sg}${y}${(au / 1e6).toFixed(1)}M` : au >= 1e3 ? `${sg}${y}${(au / 1e3).toFixed(1)}K` : `${sg}${y}${au.toFixed(0)}`; } }
  const a = Math.abs(v); const sign = v < 0 ? '-' : '';
  const f = (x) => { const s = x.toFixed(1).replace(/\.0$/, ''); return lang === 'id' ? s.replace('.', ',') : s; };
  if (a >= 1e9) return `${sign}${f(a / 1e9)}${lang === 'id' ? ' M' : 'B'}`;
  if (a >= 1e6) return `${sign}${f(a / 1e6)}${lang === 'id' ? ' jt' : 'M'}`;
  if (a >= 1e3) return `${sign}${f(a / 1e3)}${lang === 'id' ? ' rb' : 'K'}`;
  return `${sign}${Math.round(a)}`;
}
function pdfDate(dateStr, lang) {
  if (!dateStr) return '-';
  return new Date(`${dateStr}T00:00:00`).toLocaleDateString(pdfLocale(lang), { day: '2-digit', month: 'short', year: 'numeric' });
}
const pdfSafe = (s) => String(s).replace(/\s+/g, '_').replace(/[^A-Za-z0-9_\-]/g, '');

/* ---------- Shared data layer (adapters only — no new financial logic) ---------- */
function buildReportModel({ endKey, months, rows, transactions, debts, receivables, accounts, investBudgets, savingGoals, t, lang }) {
  const S = PDF_STR[lang] || PDF_STR.en;
  const keys = pdfMonthKeys(endKey, months);
  const keySet = new Set(keys);
  const rowMap = {}; (rows || []).forEach(r => { rowMap[r.monthKey] = r; });
  const zero = (k) => ({ monthKey: k, income: 0, expense: 0, debtPaid: 0, invested: 0, net: 0 });
  const monthly = keys.map(k => (rowMap[k] ? { ...rowMap[k] } : zero(k)));
  const sum = (f) => monthly.reduce((s, r) => s + (Number(r[f]) || 0), 0);
  const total = { income: sum('income'), expense: sum('expense'), debtPaid: sum('debtPaid'), invested: sum('invested'), net: sum('net') };
  const hasData = total.income + total.expense + total.debtPaid + total.invested > 0;

  const periodTx = (transactions || []).filter(tx => keySet.has(tx.date.slice(0, 7)));
  const byCatExpense = {}, byCatInvest = {}, debtPay = {};
  periodTx.forEach(tx => {
    const a = Number(tx.amount) || 0;
    if (tx.type === 'expense') byCatExpense[tx.category] = (byCatExpense[tx.category] || 0) + a;
    else if (tx.type === 'investment') byCatInvest[tx.category] = (byCatInvest[tx.category] || 0) + a;
    else if (tx.type === 'debt_payment' && !isCardPay(tx)) debtPay[tx.debtId || '_none'] = (debtPay[tx.debtId || '_none'] || 0) + a;
  });
  const catName = (c) => t.categories[c] || c;
  const expenseCats = Object.entries(byCatExpense).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1])
    .map(([c, v]) => ({ key: c, name: catName(c), amount: v, pct: total.expense > 0 ? v / total.expense : 0 }));

  // Same formulas as the Review health score: savings = (income - expense - debtPaid) / income,
  // debt ratio = remaining debt / (income x 12). For a period, income is the monthly average.
  const totalDebtRemaining = (debts || []).reduce((s, d) => s + Number(d.remaining || 0), 0);
  // Average over the months the user actually has data for (from the first active month in the range), so a 6-month
  // report on an account that only started 2 months ago isn't diluted 3x (which inflated the debt-to-income ratio).
  const firstActive = monthly.findIndex(r => (Number(r.income) || 0) + (Number(r.expense) || 0) + (Number(r.debtPaid) || 0) + (Number(r.invested) || 0) > 0);
  const activeSpan = firstActive < 0 ? months : monthly.length - firstActive;
  const avgIncome = total.income / Math.max(1, activeSpan);
  const savingsRate = total.income > 0 ? total.net / total.income : null;
  const dtiRatio = avgIncome > 0 ? totalDebtRemaining / (avgIncome * 12) : null;

  const debtRows = [];
  (debts || []).forEach(d => {
    const paid = debtPay[d.id] || 0;
    if (paid > 0 || Number(d.remaining) > 0) debtRows.push({ name: d.name, paid, remaining: Number(d.remaining) || 0 });
  });
  if (debtPay._none > 0) debtRows.push({ name: S.otherDebt, paid: debtPay._none, remaining: null });
  debtRows.sort((a, b) => b.paid - a.paid || (b.remaining || 0) - (a.remaining || 0));

  const todayStr = todayISO();
  const piutangRows = (receivables || []).filter(r => r.status !== 'paid' || (r.paidDate && keySet.has(r.paidDate.slice(0, 7))))
    .map(r => ({
      name: r.name, amount: Number(r.amount) || 0, dueDate: r.dueDate || null,
      status: r.status === 'paid' ? 'settled' : (r.dueDate && r.dueDate < todayStr ? 'late' : 'active'),
    }))
    .sort((a, b) => (a.status === 'settled') - (b.status === 'settled') || String(a.dueDate || '9999').localeCompare(String(b.dueDate || '9999')));
  const activePiutang = (receivables || []).filter(r => r.status !== 'paid').reduce((s, r) => s + (Number(r.amount) || 0), 0);
  const collected = (receivables || []).filter(r => r.status === 'paid' && r.paidDate && keySet.has(r.paidDate.slice(0, 7))).reduce((s, r) => s + (Number(r.amount) || 0), 0);

  // Investment Plan (what I intend to invest per category) vs actual contributions. Kept apart
  // from portfolio/holdings, which this report intentionally does not cover.
  const planCats = Object.entries(investBudgets || {}).filter(([, v]) => Number(v) > 0);
  const investKeys = Array.from(new Set([...planCats.map(([c]) => c), ...Object.keys(byCatInvest)]));
  const investRows = investKeys.map(c => {
    const planned = (Number(investBudgets?.[c]) || 0) * months; const actual = byCatInvest[c] || 0;
    return { name: catName(c), planned, actual, progress: planned > 0 ? actual / planned : null };
  }).sort((a, b) => b.actual - a.actual || b.planned - a.planned);

  const goals = [...(savingGoals || [])].sort((a, b) => Number(a.completed) - Number(b.completed) || b.current - a.current)
    .map(g => ({ name: g.name, target: g.target, saved: g.current, progress: g.target > 0 ? Math.min(1, g.current / g.target) : 0, completed: g.completed }));
  const goalsTarget = goals.reduce((s, g) => s + g.target, 0); const goalsSaved = goals.reduce((s, g) => s + Math.min(g.saved, g.target), 0);

  return {
    keys, monthly, total, hasData, expenseCats, totalDebtRemaining, savingsRate, dtiRatio, avgIncome,
    debtRemList: (debts || []).map(d => Number(d.remaining) || 0),
    activePiutangList: (receivables || []).filter(r => r.status !== 'paid').map(r => Number(r.amount) || 0),
    collectedList: (receivables || []).filter(r => r.status === 'paid' && r.paidDate && keySet.has(r.paidDate.slice(0, 7))).map(r => Number(r.amount) || 0),
    debtRows, piutangRows, activePiutang, collected, investRows, goals, goalsOverall: goalsTarget > 0 ? goalsSaved / goalsTarget : null,
    monthsWithDebt: monthly.filter(r => r.debtPaid > 0).length, monthsWithInvest: monthly.filter(r => r.invested > 0).length,
    periodTx, rowMap, zero,
  };
}

/* ---------- PDF drawing toolkit ---------- */
const PDF_C = {
  ink: [24, 20, 16], grey: [118, 110, 100], soft: [246, 243, 237], line: [221, 214, 202],
  gold: [184, 150, 96], goldSoft: [236, 226, 207], maroon: [122, 32, 32], sage: [96, 128, 88],
};
const PDF_M = { l: 16, r: 16, top: 26, bottom: 20 };

// Original Revinance logo: header on every page + a faint centred watermark (all downloaded PDFs).
function pdfLogo(doc, x, y, h) { doc.addImage(RV_LOGO_FULL, 'PNG', x, y, h * RV_LOGO_FULL_RATIO, h, 'rv-logo'); }
function pdfWatermark(doc, W, H) {
  const w = 120, h = w / RV_LOGO_FULL_RATIO;
  try { doc.setGState(new doc.GState({ opacity: 0.08 })); } catch { /* old jsPDF: skip opacity */ }
  doc.addImage(RV_LOGO_FULL, 'PNG', (W - w) / 2, H / 2 - h / 2, w, h, 'rv-logo');
  try { doc.setGState(new doc.GState({ opacity: 1 })); } catch { /* ignore */ }
}
function pdfNew() {
  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  doc.setFont('helvetica', 'normal');
  return { doc, W: 210, H: 297, cw: 210 - PDF_M.l - PDF_M.r, y: PDF_M.top };
}
function pdfFirstHeader(c, S, titleText, rangeText, lang) {
  const { doc } = c;
  pdfLogo(doc, PDF_M.l, 13.5, 6);
  doc.setFont('helvetica', 'bold'); doc.setFontSize(24); doc.setTextColor(...PDF_C.ink);
  doc.text(titleText, PDF_M.l, 31);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(12); doc.setTextColor(...PDF_C.grey);
  doc.text(rangeText, PDF_M.l, 38);
  doc.setFontSize(8);
  doc.text(`${S.generated}: ${new Date().toLocaleDateString(pdfLocale(lang), { day: 'numeric', month: 'long', year: 'numeric' })}`, c.W - PDF_M.r, 38, { align: 'right' });
  doc.setDrawColor(...PDF_C.gold); doc.setLineWidth(0.5); doc.line(PDF_M.l, 43, c.W - PDF_M.r, 43);
  c.y = 52;
}
function pdfNewPage(c) { c.doc.addPage(); c.y = PDF_M.top; }
function pdfEnsure(c, h) { if (c.y + h > c.H - PDF_M.bottom) pdfNewPage(c); }
function pdfSection(c, title, sub) {
  // Reserve room for the heading AND the start of what follows so a heading is never orphaned.
  pdfEnsure(c, 38);
  const { doc } = c;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(13); doc.setTextColor(...PDF_C.ink);
  doc.text(title, PDF_M.l, c.y);
  c.y += 2.5;
  doc.setDrawColor(...PDF_C.line); doc.setLineWidth(0.3); doc.line(PDF_M.l, c.y, c.W - PDF_M.r, c.y);
  c.y += 6;
  if (sub) {
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(...PDF_C.grey);
    const lines = doc.splitTextToSize(sub, c.cw); doc.text(lines, PDF_M.l, c.y); c.y += lines.length * 3.8 + 2;
  }
}
function pdfSubhead(c, text) {
  pdfEnsure(c, 30);
  c.doc.setFont('helvetica', 'bold'); c.doc.setFontSize(10); c.doc.setTextColor(...PDF_C.ink);
  c.doc.text(text, PDF_M.l, c.y); c.y += 5;
}
function pdfNote(c, text) {
  const { doc } = c;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5); doc.setTextColor(...PDF_C.grey);
  const lines = doc.splitTextToSize(text, c.cw);
  pdfEnsure(c, lines.length * 3.4 + 2);
  doc.text(lines, PDF_M.l, c.y + 1); c.y += lines.length * 3.4 + 4;
}
function pdfEmpty(c, text) {
  pdfEnsure(c, 12);
  const { doc } = c;
  doc.setFillColor(...PDF_C.soft); doc.roundedRect(PDF_M.l, c.y, c.cw, 10, 2, 2, 'F');
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.setTextColor(...PDF_C.grey);
  doc.text(text, PDF_M.l + c.cw / 2, c.y + 6.3, { align: 'center' });
  c.y += 14;
}
// Card: label (small caps grey) + big value. dark = filled ink card with light text.
function pdfCard(c, x, y, w, h, label, value, opts = {}) {
  const { doc } = c;
  if (opts.dark) { doc.setFillColor(...PDF_C.ink); doc.roundedRect(x, y, w, h, 2.5, 2.5, 'F'); }
  else { doc.setFillColor(...PDF_C.soft); doc.roundedRect(x, y, w, h, 2.5, 2.5, 'F'); }
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(...(opts.dark ? [205, 190, 160] : PDF_C.grey));
  // Long labels wrap onto a second line instead of being clipped by the card edge.
  doc.text(doc.splitTextToSize(String(label).toUpperCase(), w - 8).slice(0, 2), x + 4, y + 5.4);
  doc.setFont('helvetica', 'bold'); doc.setFontSize(opts.small ? 11 : 14);
  doc.setTextColor(...(opts.dark ? [250, 247, 240] : (opts.color || PDF_C.ink)));
  const fit = doc.splitTextToSize(String(value), w - 8)[0];
  doc.text(fit, x + 4, y + h - 5);
}
function pdfCardRow(c, cards, h, small) {
  pdfEnsure(c, h + 4);
  const gap = 4; const w = (c.cw - gap * (cards.length - 1)) / cards.length;
  cards.forEach((cd, i) => pdfCard(c, PDF_M.l + i * (w + gap), c.y, w, h, cd.label, cd.value, { dark: cd.dark, color: cd.color, small }));
  c.y += h + 4;
}
function pdfTable(c, { head, body, foot, widths, aligns, startGap = 0, fontSize = 8.5 }) {
  const { doc } = c;
  const columnStyles = {};
  head[0].forEach((_, i) => { columnStyles[i] = { halign: aligns?.[i] || 'left', cellWidth: widths?.[i] || 'auto' }; });
  autoTable(doc, {
    startY: c.y + startGap, head, body, foot: foot || undefined, showFoot: foot ? 'lastPage' : 'never',
    margin: { left: PDF_M.l, right: PDF_M.r, top: PDF_M.top, bottom: PDF_M.bottom },
    tableWidth: c.cw, theme: 'plain', rowPageBreak: 'avoid', showHead: 'everyPage',
    styles: { font: 'helvetica', fontSize, textColor: PDF_C.ink, cellPadding: { top: 2.2, bottom: 2.2, left: 2.4, right: 2.4 }, overflow: 'linebreak', valign: 'middle', lineColor: PDF_C.line, lineWidth: { bottom: 0.15 } },
    headStyles: { fillColor: PDF_C.goldSoft, textColor: PDF_C.ink, fontStyle: 'bold', fontSize: fontSize - 0.5, lineWidth: 0 },
    footStyles: { fillColor: PDF_C.soft, textColor: PDF_C.ink, fontStyle: 'bold', lineWidth: 0 },
    alternateRowStyles: { fillColor: [251, 249, 245] },
    columnStyles,
    // Header/footer cells must follow the same alignment as their column's body cells.
    didParseCell: (d) => { if (d.section !== 'body') d.cell.styles.halign = aligns?.[d.column.index] || 'left'; },
  });
  c.y = doc.lastAutoTable.finalY + 6;
}
function pdfHBars(c, items, opts = {}) {
  // items: [{label, value, display}] — horizontal bars scaled to the largest value.
  const { doc } = c; const rowH = 7.5; const labelW = 40; const valW = 30;
  pdfEnsure(c, Math.min(items.length, 4) * rowH + 4);
  const barX = PDF_M.l + labelW; const barW = c.cw - labelW - valW; const max = Math.max(...items.map(i => i.value), 1);
  items.forEach((it) => {
    pdfEnsure(c, rowH + 1);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); doc.setTextColor(...PDF_C.ink);
    doc.text(doc.splitTextToSize(it.label, labelW - 3)[0], PDF_M.l, c.y + 4.6);
    doc.setFillColor(...PDF_C.soft); doc.roundedRect(barX, c.y + 1.2, barW, 4.6, 1.2, 1.2, 'F');
    const w = Math.max(1.2, (it.value / max) * barW);
    doc.setFillColor(...(opts.color || PDF_C.gold)); doc.roundedRect(barX, c.y + 1.2, w, 4.6, 1.2, 1.2, 'F');
    doc.setFont('helvetica', 'bold'); doc.setFontSize(8); doc.setTextColor(...PDF_C.ink);
    doc.text(it.display, PDF_M.l + c.cw, c.y + 4.6, { align: 'right' });
    c.y += rowH;
  });
  c.y += 4;
}
// Grouped vertical bars (two series) with light gridlines and y-axis labels.
function pdfGroupedBars(c, { labels, a, b, nameA, nameB, h = 62, lang }) {
  const { doc } = c; pdfEnsure(c, h + 16);
  const x0 = PDF_M.l + 16; const w = c.cw - 16; const top = c.y + 6; const base = top + h - 8;
  const plotH = base - top; const max = Math.max(...a, ...b, 1);
  const niceMax = (() => { const p = Math.pow(10, Math.floor(Math.log10(max))); const n = max / p; return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * p; })();
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(...PDF_C.grey); doc.setDrawColor(...PDF_C.line); doc.setLineWidth(0.15);
  for (let i = 0; i <= 4; i++) {
    const yy = base - (plotH * i) / 4; doc.line(x0, yy, x0 + w, yy);
    doc.text(pdfAxis((niceMax * i) / 4, lang), x0 - 2, yy + 1.2, { align: 'right' });
  }
  const n = labels.length; const slot = w / n; const bw = Math.min(8, (slot - 2) / 2.3);
  labels.forEach((lb, i) => {
    const cx = x0 + slot * i + slot / 2;
    const ha = (a[i] / niceMax) * plotH; const hb = (b[i] / niceMax) * plotH;
    if (ha > 0.1) { doc.setFillColor(...PDF_C.gold); doc.rect(cx - bw - 0.3, base - ha, bw, ha, 'F'); }
    if (hb > 0.1) { doc.setFillColor(...PDF_C.ink); doc.rect(cx + 0.3, base - hb, bw, hb, 'F'); }
    doc.setFontSize(n > 8 ? 6.5 : 7.5); doc.setTextColor(...PDF_C.grey); doc.text(lb, cx, base + 4.5, { align: 'center' });
  });
  const ly = base + 9;
  doc.setFillColor(...PDF_C.gold); doc.rect(x0, ly - 2.2, 3, 3, 'F'); doc.setFontSize(7.5); doc.setTextColor(...PDF_C.ink); doc.text(nameA, x0 + 4.5, ly + 0.2);
  const ax = x0 + 8 + doc.getTextWidth(nameA) + 6;
  doc.setFillColor(...PDF_C.ink); doc.rect(ax, ly - 2.2, 3, 3, 'F'); doc.text(nameB, ax + 4.5, ly + 0.2);
  c.y = ly + 8;
}
// Net bars: positive up (ink), negative down (maroon), zero baseline in the middle.
function pdfNetBars(c, { labels, values, h = 46, lang }) {
  const { doc } = c; pdfEnsure(c, h + 10);
  const x0 = PDF_M.l + 16; const w = c.cw - 16; const top = c.y + 4; const mid = top + h / 2; const half = h / 2 - 5;
  const max = Math.max(...values.map(v => Math.abs(v)), 1);
  doc.setDrawColor(...PDF_C.line); doc.setLineWidth(0.15); doc.line(x0, mid, x0 + w, mid);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(...PDF_C.grey);
  doc.text('0', x0 - 2, mid + 1.2, { align: 'right' }); doc.text(pdfAxis(max, lang), x0 - 2, mid - half + 1.2, { align: 'right' }); doc.text(pdfAxis(-max, lang), x0 - 2, mid + half + 1.2, { align: 'right' });
  const n = labels.length; const slot = w / n; const bw = Math.min(10, slot - 3);
  labels.forEach((lb, i) => {
    const cx = x0 + slot * i + slot / 2; const v = values[i]; const bh = (Math.abs(v) / max) * half;
    if (bh > 0.1) { doc.setFillColor(...(v >= 0 ? PDF_C.ink : PDF_C.maroon)); doc.rect(cx - bw / 2, v >= 0 ? mid - bh : mid, bw, bh, 'F'); }
    doc.setFontSize(n > 8 ? 6.5 : 7.5); doc.setTextColor(...PDF_C.grey); doc.text(lb, cx, top + h + 1.5, { align: 'center' });
  });
  c.y = top + h + 8;
}
function pdfFinish(c, S, rangeText, runningTitle) {
  const { doc } = c; const n = doc.getNumberOfPages();
  for (let i = 1; i <= n; i++) {
    doc.setPage(i);
    pdfWatermark(doc, c.W, c.H);
    if (i > 1) {
      pdfLogo(doc, PDF_M.l, 9.5, 4.6);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(...PDF_C.grey); doc.text(runningTitle, c.W - PDF_M.r, 14, { align: 'right' });
      doc.setDrawColor(...PDF_C.line); doc.setLineWidth(0.2); doc.line(PDF_M.l, 17, c.W - PDF_M.r, 17);
    }
    doc.setDrawColor(...PDF_C.line); doc.setLineWidth(0.2); doc.line(PDF_M.l, c.H - 14, c.W - PDF_M.r, c.H - 14);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5); doc.setTextColor(...PDF_C.grey);
    doc.text(`${S.footer}  |  ${rangeText}`, PDF_M.l, c.H - 9);
    doc.text(`${S.page} ${i} ${S.of} ${n}`, c.W - PDF_M.r, c.H - 9, { align: 'right' });
  }
}

/* ---------- Template A: MONTHLY REPORT (detailed) ---------- */
function renderMonthlyReport(model, ctx) {
  const { t, lang, accounts, debts, endKey } = ctx; const S = PDF_STR[lang] || PDF_STR.en;
  const c = pdfNew(); const m = model.monthly[0]; const label = pdfMonthLong(endKey, lang);
  pdfFirstHeader(c, S, S.reportMonthly, label, lang);

  // Page 1 — Executive summary
  pdfSection(c, S.execSummary);
  pdfCardRow(c, [{ label: S.totalIncome, value: pdfMoney(m.income) }, { label: S.totalExpenses, value: pdfMoney(m.expense) }, { label: S.debtPayment, value: pdfMoney(m.debtPaid) }], 22, true);
  pdfCardRow(c, [{ label: S.investment, value: pdfMoney(m.invested) }, { label: S.netChange, value: pdfMoney(m.net), dark: true }], 24);
  c.y += 2; pdfSubhead(c, S.keyMetrics);
  pdfCardRow(c, [
    { label: S.savingsRate, value: pdfPct(model.savingsRate, lang) }, { label: S.dti, value: pdfPct(model.dtiRatio, lang) },
    { label: S.activeDebt, value: pdfSumMoney(model.debtRemList) }, { label: S.activePiutang, value: pdfSumMoney(model.activePiutangList) },
  ], 20, true);
  pdfNote(c, S.metricsNote);

  // Page 2 — Spending analysis
  pdfNewPage(c); pdfSection(c, S.spendingAnalysis);
  if (model.expenseCats.length === 0) pdfEmpty(c, S.noSpending);
  else {
    const top3 = model.expenseCats.slice(0, 3).reduce((s, x) => s + x.pct, 0);
    pdfCardRow(c, [{ label: S.totalExpenses, value: pdfMoney(m.expense) }, { label: S.topCategory, value: model.expenseCats[0].name }, { label: S.top3Share, value: pdfPct(top3, lang, 0) }], 20, true);
    pdfHBars(c, model.expenseCats.slice(0, 8).map(x => ({ label: x.name, value: x.amount, display: pdfMoney(x.amount) })));
    c.y += 3;
    pdfSubhead(c, S.category);
    pdfTable(c, { head: [[S.category, S.amount, S.pctOfExpenses]], body: model.expenseCats.map(x => [x.name, pdfMoney(x.amount), pdfPct(x.pct, lang)]), widths: [c.cw - 80, 48, 32], aligns: ['left', 'right', 'right'], foot: [[S.total, pdfSumMoney(model.expenseCats.map(x => x.amount)), '100%']] });
  }

  // Page 3 — Cash flow
  pdfNewPage(c); pdfSection(c, S.cashFlow, S.flowNote);
  const moneyOut = m.expense + m.debtPaid;
  pdfCardRow(c, [{ label: S.moneyIn, value: pdfMoney(m.income) }, { label: S.moneyOut, value: pdfMoney(moneyOut) }, { label: S.netChange, value: pdfMoney(m.net), dark: true }], 22, true);
  pdfTable(c, {
    head: [[S.flowItem, S.amount]],
    body: [[S.income, pdfMoney(m.income)], [`- ${S.totalExpenses}`, pdfMoney(m.expense)], [`- ${S.debtPayment}`, pdfMoney(m.debtPaid)], [`= ${S.netChange}`, pdfMoney(m.net)], [`- ${S.allocatedInvest}`, pdfMoney(m.invested)], [S.remainingAfterInvest, pdfMoney(m.net - m.invested)]],
    widths: [c.cw - 50, 50], aligns: ['left', 'right'],
  });
  // Weekly income vs spending (same transactions the totals come from)
  const [yy, mm] = endKey.split('-').map(Number); const dim = new Date(yy, mm, 0).getDate();
  const bands = [[1, 7], [8, 14], [15, 21], [22, dim]];
  const wi = bands.map(() => 0), we = bands.map(() => 0);
  model.periodTx.forEach(tx => { const d = Number(tx.date.slice(8, 10)); const bi = bands.findIndex(([a, b]) => d >= a && d <= b); const amt = Number(tx.amount) || 0; if (bi < 0) return; if (tx.type === 'income') wi[bi] += amt; else if (isSpendTx(tx)) we[bi] += amt; });
  if (wi.some(v => v > 0) || we.some(v => v > 0)) {
    pdfSubhead(c, S.weeklyFlow);
    pdfGroupedBars(c, { labels: bands.map(([a, b]) => `${S.week} ${a}-${b}`), a: wi, b: we, nameA: S.moneyIn, nameB: S.moneyOut, lang, h: 58 });
  }

  // Page 4 — Debt & Piutang
  pdfNewPage(c); pdfSection(c, S.debtAndPiutang, S.balanceNote);
  pdfSubhead(c, S.debt);
  pdfCardRow(c, [{ label: S.activeDebt, value: pdfSumMoney(model.debtRemList) }, { label: S.paymentThisMonth, value: pdfMoney(m.debtPaid) }, { label: S.dti, value: pdfPct(model.dtiRatio, lang) }], 20, true);
  if (model.debtRows.length === 0) pdfEmpty(c, S.noDebt);
  else pdfTable(c, { head: [[S.debtName, S.paymentThisMonth, S.remaining]], body: model.debtRows.map(d => [d.name, pdfMoney(d.paid), d.remaining == null ? '-' : pdfMoney(d.remaining)]), widths: [c.cw - 90, 45, 45], aligns: ['left', 'right', 'right'] });
  pdfSubhead(c, S.piutang);
  pdfCardRow(c, [{ label: S.activePiutang, value: pdfSumMoney(model.activePiutangList) }, { label: S.collected, value: pdfSumMoney(model.collectedList) }], 20, true);
  if (model.piutangRows.length === 0) pdfEmpty(c, S.noPiutang);
  else pdfTable(c, { head: [[S.personName, S.amount, S.dueDate, S.status]], body: model.piutangRows.map(p => [p.name, pdfMoney(p.amount), pdfDate(p.dueDate, lang), p.status === 'settled' ? S.stSettled : p.status === 'late' ? S.stLate : S.stActive]), widths: [c.cw - 105, 40, 38, 27], aligns: ['left', 'right', 'left', 'left'] });

  // Page 5 — Investment & Saving goals
  pdfNewPage(c); pdfSection(c, S.investmentAndGoals);
  pdfSubhead(c, S.investment);
  pdfCardRow(c, [{ label: S.investThisMonth, value: pdfMoney(m.invested) }], 18, true);
  if (model.investRows.length === 0) pdfEmpty(c, S.noInvest);
  else pdfTable(c, { head: [[`${S.investPlan} - ${S.category}`, S.planned, S.actual, S.progress]], body: model.investRows.map(r => [r.name, r.planned > 0 ? pdfMoney(r.planned) : '-', pdfMoney(r.actual), r.progress == null ? '-' : pdfPct(r.progress, lang, 0)]), widths: [c.cw - 112, 38, 38, 36], aligns: ['left', 'right', 'right', 'right'] });
  pdfSubhead(c, S.savingGoals);
  if (model.goals.length === 0) pdfEmpty(c, S.noGoals);
  else pdfTable(c, { head: [[S.goal, S.target, S.saved, S.progress]], body: model.goals.map(g => [g.name, pdfMoney(g.target), pdfMoney(g.saved), pdfPct(g.progress, lang, 0)]), widths: [c.cw - 112, 38, 38, 36], aligns: ['left', 'right', 'right', 'right'] });
  pdfNote(c, S.goalsNote);

  // Page 6 — Comparison with previous month
  const prevKey = pdfMonthKeys(endKey, 2)[0]; const prev = model.rowMap[prevKey] || model.zero(prevKey);
  pdfNewPage(c); pdfSection(c, S.comparison, `${pdfMonthLong(endKey, lang)} vs ${pdfMonthLong(prevKey, lang)}`);
  const cmp = [[S.totalIncome, 'income'], [S.totalExpenses, 'expense'], [S.debtPayment, 'debtPaid'], [S.investment, 'invested'], [S.netChange, 'net']];
  pdfTable(c, {
    head: [[S.metric, pdfMonthShort(endKey, lang) + ' ' + endKey.slice(0, 4), pdfMonthShort(prevKey, lang) + ' ' + prevKey.slice(0, 4), S.change, S.changePct]],
    body: cmp.map(([lb, f]) => { const cur = Number(m[f]) || 0, pv = Number(prev[f]) || 0; return [lb, pdfMoney(cur), pdfMoney(pv), pdfSigned(cur - pv), pv !== 0 ? `${cur - pv > 0 ? '+' : ''}${pdfPct((cur - pv) / Math.abs(pv), lang)}` : '-']; }),
    widths: [c.cw - 135, 33, 33, 36, 33], aligns: ['left', 'right', 'right', 'right', 'right'],
  });
  pdfNote(c, S.compareNote);

  // Page 7+ — Transaction detail (only groups that have data; headers repeat on page breaks)
  const accName = (id) => (accounts || []).find(a => a.id === id)?.name || '-';
  const debtName = (id) => (debts || []).find(d => d.id === id)?.name;
  const groups = [['income', S.income], ['expense', S.expenses], ['debt_payment', S.debtPayments], ['investment', S.investments]];
  const sorted = [...model.periodTx].sort((a, b) => a.date.localeCompare(b.date));
  let started = false;
  groups.forEach(([type, name]) => {
    const list = sorted.filter(tx => tx.type === type); if (list.length === 0) return;
    if (!started) { pdfNewPage(c); pdfSection(c, S.transactionDetail); started = true; }
    pdfSubhead(c, `${name} (${list.length})`);
    pdfTable(c, {
      head: [[S.date, S.description, S.category, S.account, S.amount]],
      body: list.map(tx => [pdfDate(tx.date, lang), ((type === 'debt_payment' ? debtName(tx.debtId) : null) || tx.note || (t.categories[tx.category] || tx.category || '-')) + pdfOrig(tx), type === 'debt_payment' ? S.debtPayment : (t.categories[tx.category] || tx.category || '-'), accName(tx.accountId), pdfMoney(tx.amount)]),
      foot: [[S.total, '', '', '', pdfSumMoney(list.map(x => Number(x.amount) || 0))]],
      widths: [24, c.cw - 24 - 30 - 28 - 34, 30, 28, 34], aligns: ['left', 'left', 'left', 'left', 'right'], fontSize: 8,
    });
  });

  pdfFinish(c, S, label, `${S.reportMonthly} | ${label}`);
  return c.doc;
}

/* ---------- Template B: PERIOD REPORT (strategic) ---------- */
function renderPeriodReport(model, ctx) {
  const { t, lang, months } = ctx; const S = PDF_STR[lang] || PDF_STR.en;
  const c = pdfNew(); const range = pdfRangeLabel(model.keys, lang);
  const title = months === 3 ? S.title3 : months === 6 ? S.title6 : S.title12;
  pdfFirstHeader(c, S, title, range, lang);
  const T = model.total; const avg = (v) => v / months;

  // Page 1 — Overview
  pdfSection(c, S.periodOverview);
  pdfSubhead(c, S.totalsLabel);
  pdfCardRow(c, [{ label: S.totalIncome, value: pdfMoney(T.income) }, { label: S.totalExpenses, value: pdfMoney(T.expense) }, { label: S.debtPayment, value: pdfMoney(T.debtPaid) }], 22, true);
  pdfCardRow(c, [{ label: S.investment, value: pdfMoney(T.invested) }, { label: S.netChange, value: pdfMoney(T.net), dark: true }], 24);
  c.y += 2; pdfSubhead(c, `${S.avgMonthly} (${months} ${lang === 'id' ? 'bulan' : 'months'})`);
  pdfCardRow(c, [{ label: S.avgIncome, value: pdfMoney(avg(T.income)) }, { label: S.avgExpenses, value: pdfMoney(avg(T.expense)) }], 20, true);
  pdfCardRow(c, [{ label: S.avgInvest, value: pdfMoney(avg(T.invested)) }, { label: S.avgNet, value: pdfMoney(avg(T.net)) }], 20, true);
  pdfNote(c, S.metricsNote);

  // Page 2 — Monthly trend (every month, Rp0 when empty)
  pdfNewPage(c); pdfSection(c, S.monthlyTrend);
  pdfTable(c, {
    head: [[S.month, S.totalIncome, S.totalExpenses, S.debtPayment, S.investment, S.netChange]],
    body: model.monthly.map(r => [pdfMonthLong(r.monthKey, lang), pdfMoney(r.income), pdfMoney(r.expense), pdfMoney(r.debtPaid), pdfMoney(r.invested), pdfMoney(r.net)]),
    foot: [[S.total, ...['income', 'expense', 'debtPaid', 'invested', 'net'].map(f => pdfSumMoney(model.monthly.map(r => r[f])))]],
    widths: [32, 28, 27, 27, 27, 37], aligns: ['left', 'right', 'right', 'right', 'right', 'right'], fontSize: 8,
  });

  // Page 3 — Cash flow trend
  pdfNewPage(c); pdfSection(c, S.cashFlowTrend);
  const labels = model.monthly.map(r => (months > 6 ? pdfMonthShort(r.monthKey, lang).slice(0, 3) : pdfMonthShort(r.monthKey, lang)));
  pdfSubhead(c, S.incomeVsExpenses);
  pdfGroupedBars(c, { labels, a: model.monthly.map(r => r.income), b: model.monthly.map(r => r.expense), nameA: S.totalIncome, nameB: S.totalExpenses, lang, h: 70 });
  pdfSubhead(c, S.netPerMonth);
  pdfNetBars(c, { labels, values: model.monthly.map(r => r.net), lang });

  // Page 4 — Spending overview (aggregated, top 10)
  pdfNewPage(c); pdfSection(c, S.spendingOverview);
  if (model.expenseCats.length === 0) pdfEmpty(c, S.noSpending);
  else {
    const top = model.expenseCats.slice(0, 10);
    pdfHBars(c, top.slice(0, 5).map(x => ({ label: x.name, value: x.amount, display: pdfMoney(x.amount) })));
    pdfSubhead(c, S.topCategories);
    pdfTable(c, { head: [[S.category, S.totalAmount, S.pctOfTotal, S.avgPerMonth]], body: top.map(x => [x.name, pdfMoney(x.amount), pdfPct(x.pct, lang, 0), `${pdfMoney(x.amount / months)}`]), widths: [c.cw - 112, 38, 28, 46], aligns: ['left', 'right', 'right', 'right'] });
  }

  // Page 5 — Financial behavior (period vs first/last month)
  pdfNewPage(c); pdfSection(c, S.financialBehavior);
  const first = model.monthly[0], last = model.monthly[model.monthly.length - 1];
  const sr = (r) => (r.income > 0 ? pdfPct(r.net / r.income, lang) : '-');
  pdfTable(c, {
    head: [[S.metric, S.periodCol, `${S.firstMonth} (${pdfMonthShort(first.monthKey, lang)})`, `${S.lastMonth} (${pdfMonthShort(last.monthKey, lang)})`]],
    body: [
      [S.totalIncome, pdfMoney(T.income), pdfMoney(first.income), pdfMoney(last.income)],
      [S.totalExpenses, pdfMoney(T.expense), pdfMoney(first.expense), pdfMoney(last.expense)],
      [S.savingsRate, pdfPct(model.savingsRate, lang), sr(first), sr(last)],
      [S.debtPayment, pdfMoney(T.debtPaid), pdfMoney(first.debtPaid), pdfMoney(last.debtPaid)],
      [S.investment, pdfMoney(T.invested), pdfMoney(first.invested), pdfMoney(last.invested)],
      [S.netChange, pdfMoney(T.net), pdfMoney(first.net), pdfMoney(last.net)],
    ],
    widths: [c.cw - 120, 40, 40, 40], aligns: ['left', 'right', 'right', 'right'],
  });
  pdfCardRow(c, [{ label: S.savingsRate, value: pdfPct(model.savingsRate, lang) }, { label: S.dti, value: pdfPct(model.dtiRatio, lang) }, { label: S.debtPaymentMonths, value: `${model.monthsWithDebt}/${months}` }, { label: S.investMonths, value: `${model.monthsWithInvest}/${months}` }], 20, true);
  pdfNote(c, S.metricsNote);

  // Page 6 — Debt & Piutang overview
  pdfNewPage(c); pdfSection(c, S.debtOverview, S.balanceNote);
  pdfSubhead(c, S.debt);
  pdfCardRow(c, [{ label: S.activeDebt, value: pdfSumMoney(model.debtRemList) }, { label: S.totalDebtPayments, value: pdfMoney(T.debtPaid) }, { label: S.dti, value: pdfPct(model.dtiRatio, lang) }], 20, true);
  if (model.debtRows.length === 0) pdfEmpty(c, S.noDebt);
  else pdfTable(c, { head: [[S.debtName, S.paymentInPeriod, S.remaining]], body: model.debtRows.map(d => [d.name, pdfMoney(d.paid), d.remaining == null ? '-' : pdfMoney(d.remaining)]), widths: [c.cw - 90, 45, 45], aligns: ['left', 'right', 'right'] });
  pdfSubhead(c, S.piutang);
  pdfCardRow(c, [{ label: S.activePiutang, value: pdfSumMoney(model.activePiutangList) }, { label: S.collected, value: pdfSumMoney(model.collectedList) }], 20, true);
  if (model.piutangRows.length === 0) pdfEmpty(c, S.noPiutang);
  else pdfTable(c, { head: [[S.personName, S.amount, S.dueDate, S.status]], body: model.piutangRows.map(p => [p.name, pdfMoney(p.amount), pdfDate(p.dueDate, lang), p.status === 'settled' ? S.stSettled : p.status === 'late' ? S.stLate : S.stActive]), widths: [c.cw - 105, 40, 38, 27], aligns: ['left', 'right', 'left', 'left'] });

  // Page 7 — Investment & Saving goals
  pdfNewPage(c); pdfSection(c, S.investmentAndGoals);
  pdfSubhead(c, S.investByCategory);
  pdfCardRow(c, [{ label: S.totalInvest, value: pdfMoney(T.invested) }], 18, true);
  if (model.investRows.length === 0) pdfEmpty(c, S.noInvest);
  else pdfTable(c, { head: [[`${S.investPlan} - ${S.category}`, S.planned, S.actual, S.progress]], body: model.investRows.map(r => [r.name, r.planned > 0 ? pdfMoney(r.planned) : '-', pdfMoney(r.actual), r.progress == null ? '-' : pdfPct(r.progress, lang, 0)]), widths: [c.cw - 112, 38, 38, 36], aligns: ['left', 'right', 'right', 'right'] });
  pdfSubhead(c, S.savingGoals);
  if (model.goals.length === 0) pdfEmpty(c, S.noGoals);
  else {
    pdfTable(c, { head: [[S.goal, S.target, S.saved, S.progress]], body: model.goals.map(g => [g.name, pdfMoney(g.target), pdfMoney(g.saved), pdfPct(g.progress, lang, 0)]), widths: [c.cw - 112, 38, 38, 36], aligns: ['left', 'right', 'right', 'right'] });
    if (model.goalsOverall != null) pdfNote(c, `${S.overallProgress}: ${pdfPct(model.goalsOverall, lang, 0)}. ${S.goalsNote}`);
  }

  // Page 8 — Key takeaways (strictly factual; omitted when there isn't enough data)
  const tk = [];
  const withIncome = model.monthly.filter(r => r.income > 0);
  if (months > 1 && withIncome.length > 1) { const best = withIncome.reduce((a, b) => (b.income > a.income ? b : a)); tk.push(S.tkIncomeHigh.replace('{m}', pdfMonthLong(best.monthKey, lang)).replace('{a}', pdfMoney(best.income))); }
  if (model.expenseCats.length > 0) tk.push(S.tkTopCat.replace('{c}', model.expenseCats[0].name).replace('{p}', Math.round(model.expenseCats[0].pct * 100)));
  const prevM = model.monthly[model.monthly.length - 2];
  if (prevM && prevM.expense > 0 && last.expense !== prevM.expense) { const p = Math.round((Math.abs(last.expense - prevM.expense) / prevM.expense) * 100); tk.push(S.tkExpChange.replace('{dir}', last.expense > prevM.expense ? S.up : S.down).replace('{p}', p).replace('{last}', pdfMonthLong(last.monthKey, lang)).replace('{prev}', pdfMonthLong(prevM.monthKey, lang))); }
  if (T.invested > 0) tk.push(S.tkInvestMonths.replace('{k}', model.monthsWithInvest).replace('{n}', months));
  if (T.debtPaid > 0) tk.push(S.tkDebtMonths.replace('{k}', model.monthsWithDebt).replace('{n}', months));
  if (tk.length < 5 && model.hasData) tk.push(S.tkNetPositive.replace('{k}', model.monthly.filter(r => r.net > 0).length).replace('{n}', months));
  const obs = tk.slice(0, 5);
  if (obs.length >= 2) {
    pdfNewPage(c); pdfSection(c, S.keyTakeaways);
    const { doc } = c;
    obs.forEach((line) => {
      doc.setFont('helvetica', 'normal'); doc.setFontSize(10); const lines = doc.splitTextToSize(line, c.cw - 8);
      pdfEnsure(c, lines.length * 5 + 6);
      doc.setFillColor(...PDF_C.gold); doc.circle(PDF_M.l + 1.5, c.y - 1, 0.9, 'F');
      doc.setTextColor(...PDF_C.ink); doc.text(lines, PDF_M.l + 6, c.y); c.y += lines.length * 5 + 4;
    });
  }

  pdfFinish(c, S, range, `${title} | ${range}`);
  return c.doc;
}

function pdfFileName(kind, endKey, months, lang) {
  const S = PDF_STR[lang] || PDF_STR.en;
  if (kind === 'monthly') return `REVINANCE_${S.fileMonthly}_${pdfSafe(pdfMonthLong(endKey, lang))}.pdf`;
  const keys = pdfMonthKeys(endKey, months); const a = keys[0], b = keys[keys.length - 1];
  const range = a.slice(0, 4) === b.slice(0, 4) ? `${pdfSafe(pdfMonthName(a, lang))}-${pdfSafe(pdfMonthName(b, lang))}_${b.slice(0, 4)}` : `${pdfSafe(pdfMonthLong(a, lang))}-${pdfSafe(pdfMonthLong(b, lang))}`;
  return `REVINANCE_${S.fileN(months)}_${range}.pdf`;
}
async function generateReportPdf({ kind, endKey, months, rows, transactions, debts, receivables, accounts, investBudgets, savingGoals, t, lang }) {
  await loadPdfLibs();
  const model = buildReportModel({ endKey, months: kind === 'monthly' ? 1 : months, rows, transactions, debts, receivables, accounts, investBudgets, savingGoals, t, lang });
  const doc = kind === 'monthly'
    ? renderMonthlyReport(model, { t, lang, accounts, debts, endKey })
    : renderPeriodReport(model, { t, lang, months });
  doc.save(pdfFileName(kind, endKey, months, lang));
}

/* =========================================================
   INVESTMENT PORTFOLIO (additive layer — "what I actually own")
   Kept apart from Investment Plan ("what I plan to invest"). Holdings come ONLY from the user's
   BUY/SELL history in finance_portfolio_trades; prices come from the market-prices edge function
   (hourly cache). Trades never feed expense/income/budget math. The only touch on existing
   money flow is OPTIONAL and happens exactly once, through the existing machinery:
     - BUY + account chosen  -> one normal 'investment' transaction (existing behaviour: it is
                                counted as investment, not expense, and deducts the account)
     - SELL + account chosen -> proceeds added to that account (not booked as income)
     - no account chosen     -> holdings tracking only, balances untouched
========================================================= */
