const FB_STR = {
  id: { reviewTitle: 'Beri Ulasan', featureTitle: 'Request Fitur', rating: 'Kasih rating', reviewPh: 'Ceritain pengalaman kamu pakai Revinance…', featurePh: 'Jelasin fitur yang kamu mau, atau masalah yang kamu temui…', kind: 'Jenis', kFeature: 'Fitur baru', kBug: 'Ada bug', kDelete: 'Hapus data saya', send: 'Kirim', sending: 'Mengirim…', thanks: 'Makasih! Masukan kamu udah masuk.', failed: 'Gagal kirim. Cek koneksi lalu coba lagi.', limited: 'Terlalu banyak kiriman hari ini. Coba lagi besok.', deleteNote: 'Permintaan ini akan menghapus akun dan semua datamu (maks. 30 hari). Ga bisa dibatalkan setelah diproses.', needRating: 'Pilih rating dulu ya.', needText: 'Tulis dulu sedikit ya.', close: 'Tutup' },
  en: { reviewTitle: 'Leave a Review', featureTitle: 'Feature Request', rating: 'Your rating', reviewPh: 'Tell us how Revinance is working for you…', featurePh: 'Describe the feature you want, or the problem you hit…', kind: 'Type', kFeature: 'New feature', kBug: 'Bug report', kDelete: 'Delete my data', send: 'Send', sending: 'Sending…', thanks: 'Thank you! Your message was received.', failed: 'Could not send. Check your connection and try again.', limited: 'Too many submissions today. Please try again tomorrow.', deleteNote: 'This asks us to delete your account and all your data (within 30 days). It cannot be undone once processed.', needRating: 'Please pick a rating.', needText: 'Please write a little first.', close: 'Close' },
};
// In-app feedback: stored in finance_feedback (readable only by its owner and the project admin) — no email client needed.
function FeedbackModal({ lang, mode, onClose }) {
  const F = FB_STR[lang] || FB_STR.en;
  const isReview = mode === 'review';
  const [kind, setKind] = useState('feature');
  const [rating, setRating] = useState(0);
  const [msg, setMsg] = useState('');
  const [state, setState] = useState('idle'); // idle | sending | done
  const [err, setErr] = useState('');
  async function submit(e) {
    e.preventDefault();
    if (state === 'sending') return;
    if (isReview && !rating) { setErr(F.needRating); return; }
    const text = msg.trim();
    if (!text) { setErr(F.needText); return; }
    setErr(''); setState('sending');
    try {
      const row = { kind: isReview ? 'review' : kind, message: text.slice(0, 2000), lang, app_ctx: { ua: String(navigator.userAgent || '').slice(0, 160), standalone: !!(window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) } };
      if (isReview) row.rating = rating;
      const { error } = await supabase.from('finance_feedback').insert(row);
      if (error) { setErr(/rate_limited/.test(String(error.message)) ? F.limited : F.failed); setState('idle'); return; }
      setState('done');
    } catch (x) { setErr(F.failed); setState('idle'); }
  }
  return (
    <div className="fc-modal-backdrop" onClick={onClose}>
      <form className="fc-modal" data-testid="feedback-modal" onClick={(e) => e.stopPropagation()} onSubmit={submit}>
        <div className="fc-modal-header"><span>{isReview ? F.reviewTitle : F.featureTitle}</span><button type="button" className="fc-icon-btn" onClick={onClose}><X size={16} /></button></div>
        {state === 'done' ? (
          <>
            <div className="fc-field-note" style={{ padding: '14px 0', fontSize: 14 }} data-testid="feedback-done">{F.thanks}</div>
            <div className="fc-modal-actions"><button type="button" className="fc-btn-primary" onClick={onClose}>{F.close}</button></div>
          </>
        ) : (
          <>
            {isReview ? (
              <div className="fc-field"><span>{F.rating}</span>
                <div style={{ display: 'flex', gap: 6 }} role="radiogroup" aria-label={F.rating}>
                  {[1, 2, 3, 4, 5].map(n => (
                    <button key={n} type="button" role="radio" aria-checked={rating === n} data-testid={`fb-star-${n}`} className="fc-icon-btn" onClick={() => setRating(n)} style={{ padding: 4 }}>
                      <Star size={26} color="var(--fc-gold)" fill={n <= rating ? 'var(--fc-gold)' : 'none'} />
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              <div className="fc-field"><span>{F.kind}</span>
                <div className="fc-type-toggle" style={{ marginBottom: 0 }}>
                  {[['feature', F.kFeature], ['bug', F.kBug], ['delete_data', F.kDelete]].map(([k, label]) => (
                    <button key={k} type="button" data-testid={`fb-kind-${k}`} className={`fc-type-btn ${kind === k ? 'fc-type-btn-active' : ''}`} onClick={() => setKind(k)}>{label}</button>
                  ))}
                </div>
                {kind === 'delete_data' && <div className="fc-field-warning" style={{ marginTop: 8 }}>{F.deleteNote}</div>}
              </div>
            )}
            <label className="fc-field"><textarea rows={5} maxLength={2000} className="fc-textarea" data-testid="fb-text" value={msg} onChange={(e) => setMsg(e.target.value)} placeholder={isReview ? F.reviewPh : F.featurePh} /></label>
            {err && <div className="fc-field-warning" data-testid="fb-error">{err}</div>}
            <div className="fc-modal-actions">
              <button type="button" className="fc-btn-ghost" onClick={onClose}>{t_cancel(lang)}</button>
              <button type="submit" className="fc-btn-primary" disabled={state === 'sending'} data-testid="fb-send">{state === 'sending' ? F.sending : F.send}</button>
            </div>
          </>
        )}
      </form>
    </div>
  );
}
